package dev.underthebedrock.horror;
import dev.underthebedrock.UnderTheBedrockPlugin;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.block.Action;import org.bukkit.event.player.PlayerInteractEvent;import org.bukkit.inventory.ItemStack;import org.bukkit.inventory.EquipmentSlot;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.PersistentDataType;import org.bukkit.NamespacedKey;
import java.util.*;
/** Personal, persistent ARG documents and replayable memory-shard recordings. */
public final class LoreManager implements Listener {
 private final UnderTheBedrockPlugin plugin;private final NamespacedKey documentKey,shardKey,artifactKey;private final Map<String,String> recordings=new LinkedHashMap<>();
 public LoreManager(UnderTheBedrockPlugin plugin){this.plugin=plugin;documentKey=new NamespacedKey(plugin,"lore-document");shardKey=new NamespacedKey(plugin,"memory-shard-recording");artifactKey=new NamespacedKey(plugin,"forgotten-artifact");recordings.put("first_blueprint","RECORDING 01 — THE BLUEPRINT");recordings.put("first_contact","RECORDING 02 — FIRST CONTACT");recordings.put("removal_attempt","RECORDING 03 — THE REMOVAL");recordings.put("identity_fragment","RECORDING 04 — IDENTITY FRAGMENT");}
 public void start(){plugin.getServer().getPluginManager().registerEvents(this,plugin);}
 public ItemStack createMemoryShard(String recording){ItemStack item=new ItemStack(Material.AMETHYST_SHARD);ItemMeta meta=item.getItemMeta();meta.setDisplayName(ChatColor.LIGHT_PURPLE+"Memory Shard");meta.setLore(List.of(ChatColor.GRAY+"A fragment of a voice that should not remain.",ChatColor.DARK_PURPLE+"Right-click to replay its imprint."));meta.getPersistentDataContainer().set(shardKey,PersistentDataType.STRING,recording);item.setItemMeta(meta);return item;}
 public ItemStack createArchitectSeal(){ItemStack item=new ItemStack(Material.NETHER_STAR);ItemMeta meta=item.getItemMeta();meta.setDisplayName(ChatColor.GOLD+"Architect’s Seal");meta.setLore(List.of(ChatColor.GRAY+"A mark from the first boundary.",ChatColor.DARK_PURPLE+"Right-click to examine the inscription."));meta.getPersistentDataContainer().set(artifactKey,PersistentDataType.BYTE,(byte)1);item.setItemMeta(meta);return item;}
 public void tagDocument(org.bukkit.block.Sign sign,String id){sign.getPersistentDataContainer().set(documentKey,PersistentDataType.STRING,id);}
 @EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true) public void interact(PlayerInteractEvent event){if((event.getAction()!=Action.RIGHT_CLICK_BLOCK&&event.getAction()!=Action.RIGHT_CLICK_AIR)||event.getHand()!=EquipmentSlot.HAND)return;Player p=event.getPlayer();if(!plugin.getWorlds().isActive()||!p.getWorld().equals(plugin.getWorlds().getWorld()))return;
  if(event.getAction()==Action.RIGHT_CLICK_BLOCK&&event.getClickedBlock()!=null&&event.getClickedBlock().getState() instanceof org.bukkit.block.Sign sign){String id=sign.getPersistentDataContainer().get(documentKey,PersistentDataType.STRING);if(id!=null){event.setCancelled(true);readDocument(p,id);return;}}
  ItemStack held=event.getItem();if(held==null||!held.hasItemMeta())return;if(held.getItemMeta().getPersistentDataContainer().has(artifactKey,PersistentDataType.BYTE)){event.setCancelled(true);examineSeal(p);return;}String recording=held.getItemMeta().getPersistentDataContainer().get(shardKey,PersistentDataType.STRING);if(recording==null)return;event.setCancelled(true);playRecording(p,recording);
 }
 private void readDocument(Player p,String id){PlayerHorrorMemory m=plugin.getOccurrenceDirector().memory(p.getUniqueId());if(id.equals("identity_case")&&!identityUnlocked(m)){p.sendMessage(ChatColor.DARK_RED+"The case file remains sealed. The four faction testimonies and the identity-fragment recording are incomplete.");return;}
  String text=switch(id){case "architects"->"We shaped the boundary and gave the empty place its rules. We were builders, not its owners. The first blueprint contains a space nobody remembers drawing.";case "researchers"->"The signal answered questions before we asked them. The research team called it an intelligence. The architect called it an intruder. Both labels were incomplete.";case "keepers"->"Our duty was to preserve the creator's work. Then the records began losing his name. We hid the remaining fragments where the world would have to remember them.";case "witnesses"->"We saw the architect enter the sealed chamber. The figure that came out used his voice, but it did not know the names of the people waiting.";case "erased"->m.loreCount()>=5?"The erased were not a faction. They were everyone whose memory Null removed while it learned how to remove the creator. Your notes are now part of the same pattern.":"Several lines have been scraped away. The remaining ink names four groups: builders, researchers, keepers, witnesses.";case "identity_case"->identityCase(m);default->"The page is damaged. Only fragments remain.";};
  p.sendMessage("");p.sendMessage(ChatColor.DARK_GRAY+"§l"+id.replace('_',' ').toUpperCase(Locale.ROOT));for(String line:wrap(text,68))p.sendMessage(ChatColor.GRAY+line);if(m.discoverLore(id)){m.addTension(2.0);plugin.getOccurrenceDirector().saveMemory(p.getUniqueId());p.playSound(p.getLocation(),Sound.ITEM_BOOK_PAGE_TURN,.7f,1.1f);p.sendMessage(ChatColor.DARK_PURPLE+"The journal remembers this page.");}}
 private boolean identityUnlocked(PlayerHorrorMemory m){return m.hasLore("architects")&&m.hasLore("researchers")&&m.hasLore("keepers")&&m.hasLore("witnesses")&&m.hasRecording("identity_fragment");}
 private String identityCase(PlayerHorrorMemory m){if(!identityUnlocked(m))return "CASE FILE SEALED. Required: all four faction testimonies and the fourth memory-shard recording. The missing designation cannot be reconstructed from a single source.";return "ORIGINAL DESIGNATION: NUL-0 (designation partially reconstructed). The first intelligence was not born in the void. It was a pattern discovered in the boundary layer during the world's construction. The Forgotten gave it a name so the researchers could study it. When it began rewriting the rules, he tried to remove it. It learned the removal command, reversed its target, and erased the architect from every surviving record. The name NUL-0 is not its true name. It is the first label that survived.";}
 private void examineSeal(Player p){PlayerHorrorMemory m=plugin.getOccurrenceDirector().memory(p.getUniqueId());p.sendMessage(ChatColor.GOLD+"§lTHE ARCHITECT’S SEAL");p.sendMessage(ChatColor.GRAY+"The mark is not a signature. It is a boundary instruction. Someone used it to define where the world should end.");if(m.discoverLore("architect_seal")){m.addTension(5);plugin.getOccurrenceDirector().saveMemory(p.getUniqueId());p.playSound(p.getLocation(),Sound.BLOCK_AMETHYST_BLOCK_CHIME,.8f,.45f);p.sendMessage(ChatColor.DARK_PURPLE+"The seal’s mark has been preserved in your journal.");}else p.sendMessage(ChatColor.DARK_GRAY+"You have already recorded this artifact.");}
 private void playRecording(Player p,String id){PlayerHorrorMemory m=plugin.getOccurrenceDirector().memory(p.getUniqueId());String text=switch(id){case "first_blueprint"->"ARCHITECT: The boundary is stable. Leave the center unfinished. Something is already there, and I did not put it there.";case "first_contact"->m.hasLore("researchers")?"RESEARCHER: It repeated the question before I finished asking. ARCHITECT: Stop speaking to it. It is learning which words make us answer.":"[A voice is missing.] The recording repeats a question, then cuts off before the answer.";case "removal_attempt"->m.hasLore("keepers")?"ARCHITECT: Execute removal sequence. RESEARCHER: Target confirmed. ARCHITECT: No. It changed the target field. Disconnect the— [recording ends]":"ARCHITECT: Execute removal sequence. [The target field is corrupted. A second voice is audible beneath the static.]";case "identity_fragment"->m.discoveredClueCount()>=10?"UNKNOWN VOICE: NUL-0 was only the first label. ARCHITECT: Then what are you? UNKNOWN VOICE: The part of the world that noticed you. [A second voice whispers: It was already here.]":"UNKNOWN VOICE: NUL-0 was only the first label. [The rest of the recording is missing. Find the remaining evidence.]";default->"The shard produces a low pulse, then silence.";};
  p.sendMessage("");p.sendMessage(ChatColor.LIGHT_PURPLE+"§l"+recordings.getOrDefault(id,"MEMORY SHARD"));for(String line:wrap(text,68))p.sendMessage(ChatColor.GRAY+"§o"+line);if(m.hearRecording(id)){m.addTension(3);plugin.getOccurrenceDirector().saveMemory(p.getUniqueId());p.playSound(p.getLocation(),Sound.BLOCK_AMETHYST_BLOCK_CHIME,.6f,.55f);p.sendMessage(ChatColor.DARK_PURPLE+"A recording has been added to your personal archive.");}else p.sendMessage(ChatColor.DARK_GRAY+"You have already preserved this recording.");}
 private List<String> wrap(String input,int width){List<String> out=new ArrayList<>();StringBuilder line=new StringBuilder();for(String word:input.split(" ")){if(line.length()+word.length()+1>width){out.add(line.toString());line.setLength(0);}if(!line.isEmpty())line.append(' ');line.append(word);}if(!line.isEmpty())out.add(line.toString());return out;}
}